import CtaSectionV3 from "./components/cta-section-v3"

export default function Page() {
  return <CtaSectionV3 />
}

"use client"

import { Dithering } from "@paper-design/shaders-react"

export function CtaSectionV3DitherBg() {
  return (
    <div className="cta-v3-dither-frame" aria-hidden>
      <Dithering
        className="absolute inset-0 size-full min-h-full"
        colorBack="#000000"
        colorFront="#ffffff"
        fit="cover"
        height={720}
        offsetX={-0.08}
        offsetY={-0.6}
        shape="warp"
        size={2}
        speed={0.1}
        type="2x2"
        width={1280}
      />
    </div>
  )
}

.cta-v3-dither-frame {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;

  opacity: 0.35;
}

.cta-v3-dither-frame canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
}

@media (prefers-reduced-motion: reduce) {
  .cta-v3-dither-frame {
    display: none;
  }

}
